L13_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L13_1.m_Talk_KOREA = "아마 제 베갯머리에서 거미가 나와도, 성안의 온 경비를 소집할 겁니다."
L13_1.m_fTalkTime = 0.03
