L13_1.m_Talk_ENG = "They would even call upon all the guards within the castle if so much as a spider came out from my pillowcase."
L13_1.m_Talk_TWN = "要是我的枕頭裡爬進了一隻蜘蛛，甚至也會把所有守衛都叫進來。"
L13_1.m_Talk_SCN = "要是我的枕头里爬进了一只蜘蛛，甚至也会把所有警卫都叫进来。"
