L18_1 = {}
L18_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 6600401
L18_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "농담이 아니야. 우리의 예언 중엔 아주 사소한 것이 계기가 되는 비극도 많으니까."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "冗談じゃないわ。アタシたちの予言の中には、とても些細なことがきっかけで起きる悲劇もあるんだから。"
L18_1.m_Talk_ENG = "I am not joking. Our prophecies tend to cause tragedies by even the smallest of things."
L18_1.m_Talk_TWN = "這不是玩笑，我們的預言中有很多因小事而引發的悲劇。"
L18_1.m_Talk_SCN = "这不是玩笑。我们的预言中有很多因小事而引发的悲剧。"
L18_1.m_Talk_DEU = "I am not joking. Our prophecies tend to cause tragedies by even the smallest of things."
L18_1.m_Talk_FRA = "I am not joking. Our prophecies tend to cause tragedies by even the smallest of things."
