L20_1 = {}
L20_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 6600401
L20_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L20_1.m_Talk_KOREA = "하지만 그런 작은 사소한 계기가 비극을 막아낸 역사도 적지 않죠."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "ですが、そのような些細なきっかけが悲劇を防いだ歴史も少なくありません。"
L20_1.m_Talk_ENG = "But history has told of times when those insignificant moments also stopped tragedy."
L20_1.m_Talk_TWN = "但也有不少因小小的契機而阻止了悲劇的歷史。"
L20_1.m_Talk_SCN = "但也有不少因小小的契机而阻止了悲剧的历史。"
L20_1.m_Talk_DEU = "But history has told of times when those insignificant moments also stopped tragedy."
L20_1.m_Talk_FRA = "But history has told of times when those insignificant moments also stopped tragedy."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 6600401
L21_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L21_1.m_Talk_KOREA = "한낱 인간이 수 천 년의 역사를 아우르며 칭송받는 영웅의 이야기. 멋지지 않나요?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "一介の人間が数千年にわたり称えられる英雄になる話。素晴らしいとは思いませんか？"
L21_1.m_Talk_ENG = "A hero's tale of a mere human being praised for a thousand years. Isn't that wonderful?"
L21_1.m_Talk_TWN = "一個普通人能夠跨越千年的歷史，被後世稱頌為英雄。不是很棒嗎？"
L21_1.m_Talk_SCN = "一个普通人能够跨越千年的历史，被后世称颂为英雄。不是很棒吗？"
L21_1.m_Talk_DEU = "A hero's tale of a mere human being praised for a thousand years. Isn't that wonderful?"
L21_1.m_Talk_FRA = "A hero's tale of a mere human being praised for a thousand years. Isn't that wonderful?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 6600401
L22_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
