L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L32_1.m_Talk_KOREA = "아발론의 왕은 평생에 한 번 요정에게 소원을 빌 수 있다고 하죠."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "アバロンの王は一生に一度だけ妖精に願いを叶えてもらえるそうですね。"
L32_1.m_Talk_ENG = "The king of Avalon is said to be given one wish during his lifetime."
L32_1.m_Talk_TWN = "據說阿瓦隆的王一生只能向精靈許一個願望。"
L32_1.m_Talk_SCN = "据说阿瓦隆的王一生只能向精灵许一个愿望。"
L32_1.m_Talk_DEU = "The king of Avalon is said to be given one wish during his lifetime."
L32_1.m_Talk_FRA = "The king of Avalon is said to be given one wish during his lifetime."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@33#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 6600401
L33_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L33_1.m_Talk_KOREA = "하지만 자신만을 위해 소원을 비는 것은 금기입니다."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "しかし、自分のために願うのは禁忌です。"
L33_1.m_Talk_ENG = "However, wishing something for myself is forbidden."
L33_1.m_Talk_TWN = "但為自己許願是禁忌。"
L33_1.m_Talk_SCN = "但为自己许愿是禁忌。"
L33_1.m_Talk_DEU = "However, wishing something for myself is forbidden."
L33_1.m_Talk_FRA = "However, wishing something for myself is forbidden."
