L34_1.m_CharScale = L35_1
L34_1.m_CharScaleTime = 0.01
L34_1.m_bCharPinup = true
L34_1.m_Talk_KOREA = "그래? 지금까지의 왕들은 나를 위하는 것이 곧 대국적인 일이라면서 잘만 포장하던데."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "そう？　今までの王は、自分のために願うことが世のためになるって、もっともらしく言っていたけれど。"
L34_1.m_Talk_ENG = "Is that so? Those before you have always seemed to find a way to present it to me as if it were something of national importance."
L34_1.m_Talk_TWN = "是嗎？到目前為止的王都假借著國家的名義，為自己許下了願望，並且他們包裝得很好。"
L34_1.m_Talk_SCN = "是吗？到目前为止的王们都假借着国家的名义，为自己许下了愿望，并且他们包装得很好。"
L34_1.m_Talk_DEU = "Is that so? Those before you have always seemed to find a way to present it to me as if it were something of national importance."
L34_1.m_Talk_FRA = "Is that so? Those before you have always seemed to find a way to present it to me as if it were something of national importance."
