L37_1 = {}
L37_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@37#Talk"
L37_1.m_CutScenProcessKey = 37
L37_1.m_CutScenID = 6600401
L37_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L37_1.m_Talk_KOREA = "어쩌면 제가 틀렸을지도 모르죠. 신념이란 명목으로 오기를 부리는 걸 수도 있고요."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "もしかしたら私が間違っているのかもしれません。信念という名目で、意地を張っているだけなのかも。"
L37_1.m_Talk_ENG = "Maybe I am in the wrong. Or I may be acting arrogantly in the name of faith."
L37_1.m_Talk_TWN = "也許我錯了，也許這是我以信念為名的固執。"
L37_1.m_Talk_SCN = "也许我错了，也许这是我以信念为名的固执。"
L37_1.m_Talk_DEU = "Maybe I am in the wrong. Or I may be acting arrogantly in the name of faith."
L37_1.m_Talk_FRA = "Maybe I am in the wrong. Or I may be acting arrogantly in the name of faith."
L38_1 = {}
L38_1.m_CutScenKey_Talk = "AVENGER_ACT4_INTERLUDE1@38#Talk"
L38_1.m_CutScenProcessKey = 38
L38_1.m_CutScenID = 6600401
L38_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L39_1 = "하지만 꼭 소원을 빌어야 한다면… 일평생을 바쳐도 이루지 못할 일에 쓰고 싶습니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ですが、願いを叶えてもらうなら……人生を捧げても叶えられないようなことを願いたい。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But if I were to make a wish... I want to use it on something I cannot achieve in my lifetime."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但如果一定要許願的話…我願意用它去實現一個我窮盡一生都不可能實現的願望。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "但如果一定要许愿的话……我愿意用它去实现一个我穷尽一生都不可能实现的愿望。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "But if I were to make a wish... I want to use it on something I cannot achieve in my lifetime."
L38_1.m_Talk_DEU = L39_1
L39_1 = "But if I were to make a wish... I want to use it on something I cannot achieve in my lifetime."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "AVENGER_ACT4_INTERLUDE1@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 6600401
L39_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L40_1 = "인류사는 영원하지만, 한 인간의 삶이란 건 그저 찰나일 뿐이니까요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "人類の歴史は永遠ですが、一介の人間の人生は刹那ですから。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Human history is eternal, but the life of one is but a moment."
L39_1.m_Talk_ENG = L40_1
L40_1 = "人類歷史是永恆的，但個人的生命只是瞬間。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "人类历史是永恒的，但一个人的生命只是瞬间。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Human history is eternal, but the life of one is but a moment."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Human history is eternal, but the life of one is but a moment."
L39_1.m_Talk_FRA = L40_1
