L42_1 = "걱정 마. 당신은 이미 현명한 왕이야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "心配しないで。アナタはすでに賢明な王よ。"
