L33_1[L34_1] = 30
L34_1 = "널 이렇게 만든 놈들에게 복수해달라고 해! 내가 그것들을 불태워서라도 갚아줄 테니까!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "アナタをこうしたやつらに復讐してほしいって言いなさい！　アタシがそいつらを燃やし尽くしてあげる！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Tell me to exact revenge on the ones who made you like this! I shall hail hellfire down on them!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "許願我向那些把你變成這樣的傢伙復仇！我會將他們燒成灰燼來為你報仇！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "许愿我向那些把你变成这样的家伙复仇！我会将他们烧成灰烬来为你报仇！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Tell me to exact revenge on the ones who made you like this! I shall hail hellfire down on them!"
L33_1.m_Talk_DEU = L34_1
