L44_1 = "인간의 삶은… 길어야 고작 백 년을 넘기지 못합니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "人間の人生は……長くても百年は越えません。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "The lifespan of a human... is shy of just a hundred years."
L43_1.m_Talk_ENG = L44_1
L44_1 = "人類的生命…就算再長也不過百年。"
