L44_1.m_CharStrID = "ARTHUR_ROOT_NPC_NULL"
L45_1 = "어리석은 죄인도… 용감한 영웅도… 결국 세월이 흘러 역사 속으로 사라지고 맙니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "愚かな罪人も……勇敢な英雄も……結局は月日が経ち、歴史の中へと消えてしまいます。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Foolish sinners... and courageous heroes... all fade away into history with time."
L44_1.m_Talk_ENG = L45_1
L45_1 = "愚蠢的罪人…勇敢的英雄…最終都會隨著時間的流逝消失在歷史中。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "愚蠢的罪人……勇敢的英雄……最终都会随着时间的流逝消失在历史中。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Foolish sinners... and courageous heroes... all fade away into history with time."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Foolish sinners... and courageous heroes... all fade away into history with time."
