L19_1 = "죄인은 왕의 형제라는 신분을 이용해 왕위를 찬탈하고자 반역이란 만행을 저질렀다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "罪人は王の兄弟であるという身分を利用し、王位を簒奪しようと反逆という蛮行を犯した。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "The sinner has used his status as the king's brother to commit treason and usurp the throne."
L18_1.m_Talk_ENG = L19_1
L19_1 = "罪人利用王弟的身份，企圖篡奪王位，犯下了叛逆的罪行。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "罪人利用王弟的身份，企图篡夺王位，犯下了叛逆的罪行。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "The sinner has used his status as the king's brother to commit treason and usurp the throne."
L18_1.m_Talk_DEU = L19_1
L19_1 = "The sinner has used his status as the king's brother to commit treason and usurp the throne."
