L19_1.m_Pos = "C"
L20_1 = "감히 아발론의 왕을 시해한 죄는 고작 한 번의 죽음으로 끝나지 않을 테니…"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "アバロンの王を弑した罪は、一度だけの死では償いきれない……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "The sin for assassinating the king of Avalon will not end with a single death."
L19_1.m_Talk_ENG = L20_1
L20_1 = "膽敢弑殺阿瓦隆之王的罪行，不會僅僅以一次死亡結束…"
L19_1.m_Talk_TWN = L20_1
L20_1 = "胆敢弑杀阿瓦隆之王的罪行，不会仅仅以一次死亡结束……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "The sin for assassinating the king of Avalon will not end with a single death."
L19_1.m_Talk_DEU = L20_1
L20_1 = "The sin for assassinating the king of Avalon will not end with a single death."
L19_1.m_Talk_FRA = L20_1
