L20_1.m_Pos = "C"
L21_1 = "그 영혼에 반역자의 낙인을 새겨, 영원히 그 죄업의 무게를 짊어지게 될 것이다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "その魂に反逆者の烙印を刻み、永遠にその業を背負いなさい。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Your soul will be branded with the mark of the traitor, and you will bear the weight of your sin forever."
L20_1.m_Talk_ENG = L21_1
L21_1 = "我將在你等的靈魂上烙下叛徒的印記，永遠背負罪孽的重擔。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "我将在你等的灵魂上烙下叛逆者的印记，永远背负罪孽的重担。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Your soul will be branded with the mark of the traitor, and you will bear the weight of your sin forever."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Your soul will be branded with the mark of the traitor, and you will bear the weight of your sin forever."
