L24_1 = "AB_UI_UNIT_VOICE_NKM_OPR_ROOT_DRUID_IN_STORY_22"
L22_1[L23_1] = L24_1
L23_1 = " <color=#ffd34c>반역자에게 죽은 아발론의 옛왕이 훗날 동토에서 다시 태어나 그루터기를 이끌리라.</color>"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "m_bTalkCenterFadeIn"
L22_1[L23_1] = true
L23_1 = " <color=#ffd34c>反逆者に殺されたアバロンの昔の王が近い将来、凍土で生まれ変わり、切り株を導くであろう。</color>"
L22_1.m_Talk_JPN = L23_1
L23_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L22_1.m_Talk_ENG = L23_1
L23_1 = "<color=#ffd34c>遭叛徒殺害的阿瓦隆國王，將來會在凍土重生並帶領木墩。</color>"
L22_1.m_Talk_TWN = L23_1
L23_1 = "<color=#ffd34c>被叛逆者杀死的阿瓦隆旧王将会在冻土中重生，并带领树桩。</color>"
L22_1.m_Talk_SCN = L23_1
L23_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L22_1.m_Talk_DEU = L23_1
L23_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L22_1.m_Talk_FRA = L23_1
