L36_1 = "AVENGER_ACT4_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 6600401
