L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L36_1 = " <color=#ffd34c>반역자에게 죽은 아발론의 옛왕이 훗날 동토에서 다시 태어나 그루터기를 이끌리라.</color>"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = " <color=#ffd34c>反逆者に殺されたアバロンの昔の王が近い将来、凍土で生まれ変わり、切り株を導くであろう。</color>"
L35_1.m_Talk_JPN = L36_1
L36_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L35_1.m_Talk_ENG = L36_1
L36_1 = "<color=#ffd34c>遭叛徒殺害的阿瓦隆國王，將來會在凍土重生並帶領木墩。</color>"
L35_1.m_Talk_TWN = L36_1
L36_1 = "<color=#ffd34c>被叛逆者杀死的阿瓦隆旧王将会在冻土中重生，并带领树桩。</color>"
L35_1.m_Talk_SCN = L36_1
L36_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L35_1.m_Talk_DEU = L36_1
L36_1 = "<color=#ffd34c>The old king of Avalon, slain by the traitor, will be reborn in the gelid lands and lead the Stump.</color>"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
