L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 6600401
L36_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L37_1 = " <color=#ffd34c>뿔을 갖고 태어난 그녀는 자신이 사랑한 고향을 지켜내고, 그루터기의 악마에게 심장을 잃을지니.</color>"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = " <color=#ffd34c>ツノを持って生まれた彼女は、自分が愛した故郷を守り抜き、切り株の悪魔によって心臓を失うであろう。</color>"
L36_1.m_Talk_JPN = L37_1
L37_1 = "<color=#ffd34c>The girl born with a horn will protect her home, and she will lose her heart to the devil of the Stump.</color>"
L36_1.m_Talk_ENG = L37_1
L37_1 = "<color=#ffd34c>她將帶著角出生，守護她所愛的故鄉，最後被木墩的魔鬼奪走心臟。</color>"
L36_1.m_Talk_TWN = L37_1
L37_1 = "<color=#ffd34c>她将带着角出生，守护她所爱的故乡，最后被树桩的恶魔夺走心脏。</color>"
L36_1.m_Talk_SCN = L37_1
L37_1 = "<color=#ffd34c>The girl born with a horn will protect her home, and she will lose her heart to the devil of the Stump.</color>"
L36_1.m_Talk_DEU = L37_1
L37_1 = "<color=#ffd34c>The girl born with a horn will protect her home, and she will lose her heart to the devil of the Stump.</color>"
L36_1.m_Talk_FRA = L37_1
