L28_1 = "AVENGER_ACT4_INTERLUDE1@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 6600401
L27_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
