L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "인간은 자신의 만족을 위해서라면, 짧은 생을 담보로 어떤 짓도 서슴지 않아."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "人間は自分の欲望のためなら、その短い命をかけてなんでもするわ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Humans will do anything for their own satisfaction, even if it means putting their short lives at risk."
L27_1.m_Talk_ENG = L28_1
L28_1 = "人類為了自身的滿足，不惜以短暫的生命為代價做任何事情。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "人类为了自身的满足，不惜以短暂的生命为代价做任何事情。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Humans will do anything for their own satisfaction, even if it means putting their short lives at risk."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Humans will do anything for their own satisfaction, even if it means putting their short lives at risk."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
