L28_1.m_Pos = "C"
L29_1 = "종말로부터 살아남기 위해 널 희생시키려 했던 그들처럼 말이야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "終末から生き残るため、アナタを犠牲にしようとした彼らのように。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Just like how they tried to sacrifice you in order to save themselves from the apocalypse."
L28_1.m_Talk_ENG = L29_1
L29_1 = "就像那些為了從末日中生存下來，而試圖犧牲你的人一樣。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "就像那些为了从末日中生存下来而试图牺牲你的人一样。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Just like how they tried to sacrifice you in order to save themselves from the apocalypse."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Just like how they tried to sacrifice you in order to save themselves from the apocalypse."
L28_1.m_Talk_FRA = L29_1
