L32_1 = "AVENGER_ACT4_INTERLUDE1@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 6600401
L31_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "그런 너희를 기꺼이 가르치고 역병을 치료했던 건, 어디까지나 이용하기 위해서였어."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そんなアナタたちを喜んで教育して疫病を治療したのは、あくまでも利用するためだったの。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "The only reason I taught and treated you all is to take advantage of you all."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我教導你們並治療瘟疫，只是為了利用你們而已。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "我教导你们并治疗瘟疫，只是为了利用你们而已。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "The only reason I taught and treated you all is to take advantage of you all."
L31_1.m_Talk_DEU = L32_1
L32_1 = "The only reason I taught and treated you all is to take advantage of you all."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "AVENGER_ACT4_INTERLUDE1@232#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 6600401
L32_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "무지하고 병든 인간은 쓸모가 없으니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "無知で病気にかかった人間は利用する価値がないから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "For the ignorant and the ill are of no use to me."
L32_1.m_Talk_ENG = L33_1
L33_1 = "無知又孱弱的人是沒有用的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "无知又病弱的人是没有用的。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "For the ignorant and the ill are of no use to me."
L32_1.m_Talk_DEU = L33_1
L33_1 = "For the ignorant and the ill are of no use to me."
L32_1.m_Talk_FRA = L33_1
