L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 6600401
L33_1.m_CutScenStrID = "AVENGER_ACT4_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "낙원문을 완성하려면, 목숨 바쳐 적철을 모으고 내 연구를 도울 존재가 필요했거든."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "楽園の門を完成するためには、命を捧げて赤鉄を集め、アタシの研究を手伝ってくれる存在が必要だったのよ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "To complete Avalon's Gate, I needed people who were willing to risk their lives to gather Violarite to further my research."
L33_1.m_Talk_ENG = L34_1
L34_1 = "為了完成樂園門，需要願意冒著生命危險收集赤鐵，並協助我研究的人類。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "为了完成门，需要愿意冒着生命危险收集赤铁并协助我研究的人类。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "To complete Avalon's Gate, I needed people who were willing to risk their lives to gather Violarite to further my research."
L33_1.m_Talk_DEU = L34_1
L34_1 = "To complete Avalon's Gate, I needed people who were willing to risk their lives to gather Violarite to further my research."
L33_1.m_Talk_FRA = L34_1
