L35_1 = "그럼 저를 구한 것도…! 그저 이용하기 위해서일 뿐이었나요?!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "じゃあ、私のことを助けてくれたのも……！　利用するためだったんですか！？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Then your saving me was also...! Just to take advantage of me?!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "那你救我…也只是為了利用我嗎？！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "那你救我……也只是为了利用我吗？！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Then your saving me was also...! Just to take advantage of me?!"
