L41_1 = "전… 그 낙인 때문에 가족과 평생을 숨어 살았어요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私は……この烙印のせいで家族とずっと隠れて暮らしていました。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "My... family and I had to live in hiding all our lives because of this mark."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我…因為那個烙印，和家人一輩子都在躲藏。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "我……因为那个烙印，和家人一辈子都在躲藏。"
