L42_1 = "낙인이 있다는 이유로 고향에서 모함을 당해 쫓겨났고, 이 그루터기에서도 종말을 불러올 거라며 멸시당했어요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "烙印があるのを理由に故郷から陥られ追い出されて、この切り株でも終末を招と軽蔑されたんです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "This mark is why I was banished from my home, and even despised for bringing the apocalypse to the Stump by the villagers."
L41_1.m_Talk_ENG = L42_1
L42_1 = "因為這個烙印，我在故鄉被誣陷、被驅逐，在這片土地上也被蔑視為會帶來末日的人。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "因为这个烙印，我在故乡被诬陷、被驱逐，在这片土地上也被蔑视为会带来末日的人。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "This mark is why I was banished from my home, and even despised for bringing the apocalypse to the Stump by the villagers."
