L8_1.m_fTalkTime = 0.03
L9_1 = "黄金の木の予言に、因果なんてなんの意味もないの。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Causality has no meaning in the Golden Tree's prophecy."
